for(const id of ['cleaning-services-jalandhar','reddit-cleaning-questions-jalandhar'])
 Object.assign(blogArticles[id],{datePublished:'2026-09-13',dateModified:'2026-09-13'});

const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
// Formatted from the ISO date so a new article cannot inherit a stale visible date.
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const longDate=iso=>{const [y,m,d]=iso.split('-').map(Number);return `${d} ${MONTHS[m-1]} ${y}`;};
export function renderArticle(a){
 const update=a.dateModified?`<time datetime="${esc(a.dateModified)}">Updated ${longDate(a.dateModified)}</time>`:'';
 const author=a.author?`<span>By ${esc(typeof a.author==='string'?a.author:a.author.name)}</span>`:'';
 return `<section class="page-intro container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/blog/">Cleaning Journal</a></nav><span class="eyebrow">CLEANING JOURNAL</span><h1>${esc(a.title)}</h1><p>${esc(a.description)}</p><p class="article-publication"><span>CleanNest Cleaning Journal</span>${author}${update}</p></section><article class="container prose">${a.sections.map(([heading,body])=>`<section><h2>${esc(heading)}</h2>${body}</section>`).join('')}</article>`;
}
